import { Fragment } from "react";

import { cn } from "@/lib/utils";

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";

type BreadcrumbLink = {
  link?: string;
  label: string;
};

interface ProductCategory {
  title: string;
  description: string;
  background: string;
}

interface ProductCategories4Props extends ProductCategory {
  breadcrumb: BreadcrumbLink[];
  className?: string;
}

const BreadcrumbLinks = [
  {
    label: "Home",
  },
  {
    label: "Handbags",
    link: "#",
  },
];

const PRODUCT_CATEGORY: ProductCategory = {
  background: "https://deifkwefumgah.cloudfront.net/shadcnblocks/block/ecommerce/clothes/Luxurious-Handbag-Display-2.png",
  title: "Handbags",
  description:
    "Explore our collection of handbags, designed for style and practicality to complement every occasion.",
};

const ProductCategories4 = ({
  breadcrumb = BreadcrumbLinks,
  title = PRODUCT_CATEGORY.title,
  description = PRODUCT_CATEGORY.description,
  background = PRODUCT_CATEGORY.background,
  className,
}: ProductCategories4Props) => {
  return (
    <section className={cn("py-32", className)}>
      <div
        style={{
          backgroundImage: `url(${background})`,
        }}
        className="relative bg-cover bg-center bg-no-repeat before:absolute before:inset-0 before:bg-black/30"
      >
        <div className="relative z-10 container flex min-h-80 flex-col py-4">
          <div>
            <ProductsCategoryBreadcrumb links={breadcrumb} />
          </div>
          <div className="flex flex-1 items-center">
            <div className="space-y-4">
              <h1 className="text-2xl leading-tight font-medium text-white sm:text-3xl md:text-4xl lg:text-5xl">
                {title}
              </h1>
              <p className="max-w-100 text-balance text-white/80">
                {description}
              </p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

const ProductsCategoryBreadcrumb = ({ links }: { links: BreadcrumbLink[] }) => {
  return (
    <Breadcrumb>
      <BreadcrumbList>
        {links.map(({ label, link }, index) => {
          const isLast = index === links.length - 1;

          return (
            <Fragment key={label}>
              <BreadcrumbItem>
                {isLast ? (
                  <BreadcrumbPage className="text-white/70">
                    {label}
                  </BreadcrumbPage>
                ) : (
                  <BreadcrumbLink
                    href={link}
                    className="cursor-pointer text-white/70 hover:text-white"
                  >
                    {label}
                  </BreadcrumbLink>
                )}
              </BreadcrumbItem>
              {!isLast && (
                <BreadcrumbSeparator className="text-white/70">
                  /
                </BreadcrumbSeparator>
              )}
            </Fragment>
          );
        })}
      </BreadcrumbList>
    </Breadcrumb>
  );
};

export { ProductCategories4 };

import { type ClassValue, clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { ChevronRight, MoreHorizontal } from "lucide-react"

import { cn } from "@/lib/utils"

function Breadcrumb({ ...props }: React.ComponentProps<"nav">) {
  return <nav aria-label="breadcrumb" data-slot="breadcrumb" {...props} />
}

function BreadcrumbList({ className, ...props }: React.ComponentProps<"ol">) {
  return (
    <ol
      data-slot="breadcrumb-list"
      className={cn(
        "text-muted-foreground flex flex-wrap items-center gap-1.5 text-sm break-words sm:gap-2.5",
        className
      )}
      {...props}
    />
  )
}

function BreadcrumbItem({ className, ...props }: React.ComponentProps<"li">) {
  return (
    <li
      data-slot="breadcrumb-item"
      className={cn("inline-flex items-center gap-1.5", className)}
      {...props}
    />
  )
}

function BreadcrumbLink({
  asChild,
  className,
  ...props
}: React.ComponentProps<"a"> & {
  asChild?: boolean
}) {
  const Comp = asChild ? Slot : "a"

  return (
    <Comp
      data-slot="breadcrumb-link"
      className={cn("hover:text-foreground transition-colors", className)}
      {...props}
    />
  )
}

function BreadcrumbPage({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="breadcrumb-page"
      role="link"
      aria-disabled="true"
      aria-current="page"
      className={cn("text-foreground font-normal", className)}
      {...props}
    />
  )
}

function BreadcrumbSeparator({
  children,
  className,
  ...props
}: React.ComponentProps<"li">) {
  return (
    <li
      data-slot="breadcrumb-separator"
      role="presentation"
      aria-hidden="true"
      className={cn("[&>svg]:size-3.5", className)}
      {...props}
    >
      {children ?? <ChevronRight />}
    </li>
  )
}

function BreadcrumbEllipsis({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="breadcrumb-ellipsis"
      role="presentation"
      aria-hidden="true"
      className={cn("flex size-9 items-center justify-center", className)}
      {...props}
    >
      <MoreHorizontal className="size-4" />
      <span className="sr-only">More</span>
    </span>
  )
}

export {
  Breadcrumb,
  BreadcrumbList,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbPage,
  BreadcrumbSeparator,
  BreadcrumbEllipsis,
}
